    source_run_id: id,
    eligible: eligible,
    degraded_included: eligible && degraded_included,
    quality_status: quality_status,
    data_mode: data_mode,
    review_status: review_status || (/(^|; )pending_review/.test(flags) ? 'pending' : ''),
    warning: eligible ? warning : '',
