  const selfAttestsLive = (dm === 'live' || dm === 'production') &&
    (qs === '' || qs === 'healthy' || (qs === 'degraded' && allowDegraded)) && !reportFalse;
  // explicit operator opt-in to a fixture/manual report verifies that data too (it is watermarked downstream)
