// v0.3: reads the APPENDED report row from $input so both branches (deterministic / Claude-merged) report
// the real llm_status / token counts / cost in result_summary.
function str(v){return v==null?'':String(v).trim();}
const cfg=$('Set Report Config').first().json;
const det=$('Build Deterministic Report').first().json;
const rep=Object.assign({},det,($input.first()&&$input.first().json)||{});
const llmUsed=str(rep.llm_status)!==''&&str(rep.llm_status)!=='disabled';
return [{ json: {
  agent_request_id:str(cfg.agent_request_id),
  created_at:str(cfg.created_at),
  requested_by:str(cfg.requested_by)||'operator',
  request_text:'Build market intelligence report v0.3 from WF10 tabs + competitor_site_snapshots + public_lead_signals',
  request_type:'report_summary',
  source_scope:'business_queues',
  platforms:'',
  query:'wf10_run='+str(rep.wf10_run_id),
  region:str(cfg.region),
  service_focus:str(cfg.niche_id),
  requested_limit:0,
  status:'completed',
  plan_summary:'WF12 Report Builder v0.3 (DEC-128): deterministic stakeholder report (executive digest, website block, public lead/audience block, action blocks) + optional approval/budget-gated Claude summary (DEC-112/122).',
  estimated_source_cost_usd:0,
  estimated_analysis_cost_usd:Number(rep.llm_cost_usd)||0,
  approval_required:false,
  approved_by:'',
  approved_at:'',
  result_summary:'report_id='+str(rep.report_id)+'; report_type='+str(rep.report_type)+'; wf10_run_id='+str(rep.wf10_run_id)+'; prev='+(str(rep.prev_wf10_run_id)||'none')+'; rows_after_filters='+rep.rows_after_filters+'; llm_status='+(str(rep.llm_status)||'disabled')+'; llm_input_tokens='+(Number(rep.llm_input_tokens)||0)+'; llm_output_tokens='+(Number(rep.llm_output_tokens)||0)+'; llm_cost_usd='+(Number(rep.llm_cost_usd)||0)+(str(rep.llm_quality_flags)?('; llm_quality_flags='+str(rep.llm_quality_flags)):'')+'; delivered_to=none.',
  next_action:(str(rep.report_type)==='no_data_notice')?'no_data; broaden filters or source scope, then re-run WF10 and WF12.':(llmUsed?'Review the report row incl. llm_summary_ru/llm_quality_flags; verify Claude added no facts absent from the deterministic report; record cost in COSTS_AND_LIMITS.md.':'Review the market_intelligence_reports row; Telegram delivery and optional Claude summary are separate gated steps (DEC-112).'),
  notes:'WF12 v0.3 stakeholder Report Builder; source_mix='+str(rep.source_mix)+'; llm '+(llmUsed?('used under approval + budget guard, cost_usd='+(Number(rep.llm_cost_usd)||0)):'disabled')+'; no Telegram send; no outreach.'
}}];

// Final run summary. No external calls.
function str(v){return v==null?'':String(v).trim();}
const cfg=$('Set Report Config').first().json;
let rep=$('Build Deterministic Report').first().json;
try{ rep=Object.assign({},rep,$('Append market_intelligence_reports').first().json); }catch(e){}
return [{ json: {
  workflow:'12 - Market Intelligence Report Builder (v0.3 stakeholder report)',
  report_id:str(rep.report_id),
  report_type:str(rep.report_type),
  wf10_run_id:str(rep.wf10_run_id),
  prev_wf10_run_id:str(rep.prev_wf10_run_id)||'(none)',
  rows_after_filters:rep.rows_after_filters,
  top_competitors:str(rep.top_competitors),
  top_angles:str(rep.top_angles),
  report_markdown:(function(){var m=str(rep.report_markdown);var ls=str(rep.llm_summary_ru);
    if(ls){m+='\n\n\u0412\u044b\u0432\u043e\u0434\u044b \u0438 \u0440\u0435\u043a\u043e\u043c\u0435\u043d\u0434\u0430\u0446\u0438\u0438:\n'+ls;
      var lr=str(rep.llm_recommendations_ru);if(lr)m+='\n'+lr;}
    return m;})(),
  summary_text:str(rep.llm_summary_ru),
  report_bundle:str(rep.report_bundle),
  source_mix:str(rep.source_mix),
  llm_status:str(rep.llm_status)||'disabled',
  llm_cost_usd:Number(rep.llm_cost_usd)||0,
  llm_quality_flags:str(rep.llm_quality_flags),
  telegram_send:false,
  delivered_to:'none',
  next_action:(str(rep.report_type)==='no_data_notice')?'no_data report written; broaden filters/source scope before the next WF10 run.':'Inspect market_intelligence_reports + agent_requests + live_source_runs rows. Trends need >=2 WF10 runs. Claude summary / Telegram delivery = separate gated steps.'
}}];

// Build the evidence-bound Claude summary prompt v0.3 (DEC-122/128) + BUDGET GUARD (throws BEFORE the
// HTTP node). FACTS ONLY: deterministic report fields + aggregate audience/lead-signal summaries — never
// raw personal text dumps, never contact fields, never raw_market_records rows.
function str(v){return v==null?'':String(v).trim();}
function cut(s,n){s=str(s);return s.length>n?s.slice(0,n):s;}
const cfg=$('Set Report Config').first().json;
const rep=$('Build Deterministic Report').first().json;
const sys='Ты — аналитик рынка для руководителя кредитно-брокерской компании. Тебе дан ДЕТЕРМИНИРОВАННЫЙ отчёт (факты, собранные пайплайном). ЖЁСТКИЕ ПРАВИЛА: (1) НЕ выдумывай факты, конкурентов, цифры, цены, тренды; (2) НЕ упоминай и не выводи контакты; (3) НЕ рекомендуй аутрич/рассылки/обзвоны и не считай публичные профили разрешением на контакт; (4) если данных мало — прямо скажи об этом в source_limitations; (5) отвечай ТОЛЬКО валидным JSON-объектом без markdown и пояснений, ключи: executive_summary_ru (строка, до 120 слов), key_findings (массив строк, 3-6), market_risks (массив строк, 2-4), recommended_next_actions (массив строк, 3-5, только внутренние действия: контент, мониторинг, проверка данных), content_recommendations (массив строк, 2-4), source_limitations (массив строк, 1-3). Всё на русском.';
const facts={ report_id:str(rep.report_id), niche:str(rep.niche_id), region:str(rep.region), wf10_run_id:str(rep.wf10_run_id), prev_wf10_run_id:str(rep.prev_wf10_run_id), rows_after_filters:rep.rows_after_filters, source_mix:str(rep.source_mix), top_competitors:str(rep.top_competitors), top_angles:str(rep.top_angles), audience_and_public_lead_signal_aggregates:str(rep.audience_summary), content_plan_ref:str(rep.content_plan_ref) };
// --- budget guard (DEC-128): hard input cap + cost estimate BEFORE any HTTP call.
const maxInChars=Number(cfg.llm_max_input_chars)||8000;
const maxCost=Number(cfg.llm_max_estimated_cost_usd)||0.10;
const maxOut=Number(cfg.llm_max_tokens)||1200;
const userText='Детерминированный отчёт (JSON, единственный источник фактов):\n'+cut(JSON.stringify(facts),maxInChars);
const estInputTokens=Math.ceil((sys.length+userText.length)/4)+50;
const estCost=Math.round(((estInputTokens*(Number(cfg.llm_input_price_per_mtok)||3.0)+maxOut*(Number(cfg.llm_output_price_per_mtok)||15.0))/1000000)*10000)/10000;
if(estCost>maxCost){
  throw new Error('WF12 Claude budget guard (DEC-128): estimated cost $'+estCost+' exceeds llm_max_estimated_cost_usd=$'+maxCost+' (est input tokens='+estInputTokens+', max output tokens='+maxOut+'). Reduce llm_max_tokens / llm_max_input_chars or raise the budget consciously. No API call was made.');
}
const body={ model:str(cfg.llm_model)||'claude-sonnet-4-6', max_tokens:maxOut, system:sys, messages:[{ role:'user', content:userText }] };
return [{ json: Object.assign({}, rep, { llm_request_body: body, llm_facts_string: JSON.stringify(facts), llm_estimated_cost_usd: estCost, llm_estimated_input_tokens: estInputTokens }) }];

// Merge the Claude summary into the report row + track cost + quality flags (DEC-122/128). If the HTTP
// placeholder is still DISABLED, items pass through WITHOUT a Claude response body — this node then throws,
// so no fabricated summary can ever be written. With a real response: parse the JSON sections, compute cost
// (usage tokens x configured prices) and fill the llm_* columns of the 25-col report row.
function str(v){return v==null?'':String(v).trim();}
function arr(v){return Array.isArray(v)?v.map(x=>str(x)).filter(Boolean):[];}
const cfg=$('Set Report Config').first().json;
const prompt=$('Build Claude Summary Prompt').first().json;
const rep=$('Build Deterministic Report').first().json;
const resp=$input.first().json;
const content=resp&&Array.isArray(resp.content)?resp.content:null;
if(!content){
  throw new Error('WF12 Claude merge: no API response — the Claude branch returned no response. Default runs keep the deterministic report ($0); the Claude node is enabled in JSON but stays inert unless enable_llm_summary=true + approval token + budget allow it.');
}
let text='';for(const b of content){ if(b&&b.type==='text'&&str(b.text))text+=b.text; }
if(resp.stop_reason==='refusal'||!str(text)){ throw new Error('WF12 Claude merge: empty or refused summary (stop_reason='+str(resp.stop_reason)+') — keep the deterministic report; investigate before retrying.'); }
const u=resp.usage||{};
const inTok=Number(u.input_tokens)||0, outTok=Number(u.output_tokens)||0;
const cost=Math.round(((inTok*(Number(cfg.llm_input_price_per_mtok)||3.0)+outTok*(Number(cfg.llm_output_price_per_mtok)||15.0))/1000000)*10000)/10000;
// --- parse the required JSON sections
const flags=[];
let parsed=null;
try{ parsed=JSON.parse(str(text).replace(/^```(json)?/,'').replace(/```$/,'').trim()); }catch(e){ parsed=null; }
if(resp.stop_reason==='max_tokens')flags.push('truncated_max_tokens');
let summaryRu='', recsRu='';
if(parsed&&typeof parsed==='object'){
  const kf=arr(parsed.key_findings), mr=arr(parsed.market_risks), na=arr(parsed.recommended_next_actions), cr=arr(parsed.content_recommendations), sl=arr(parsed.source_limitations);
  summaryRu=[str(parsed.executive_summary_ru), kf.length?('Ключевые выводы: '+kf.join(' · ')):'', mr.length?('Риски: '+mr.join(' · ')):'', sl.length?('Ограничения источников: '+sl.join(' · ')):''].filter(Boolean).join('\n');
  recsRu=[na.length?('Действия: '+na.join(' · ')):'', cr.length?('Контент: '+cr.join(' · ')):''].filter(Boolean).join('\n');
  if(!str(parsed.executive_summary_ru))flags.push('missing_executive_summary');
  if(!kf.length)flags.push('missing_key_findings');
  // RU-NARRATIVE guard (MVP-F): a summary with no Cyrillic is not a Russian report narrative — treat it as
  // invalid and keep the deterministic facts (same fallback as non-JSON output; nothing malformed persists).
  if(str(parsed.executive_summary_ru)&&!/[а-яё]/i.test(str(parsed.executive_summary_ru))){
    return [{ json: Object.assign({}, rep, { llm_status:'fallback_deterministic', llm_model:str(cfg.llm_model)||'claude-sonnet-4-6', llm_input_tokens:inTok, llm_output_tokens:outTok, llm_cost_usd:cost, llm_summary_ru:'', llm_recommendations_ru:'', llm_quality_flags:'non_russian_summary; fell_back_to_deterministic', notes:str(rep.notes)+' || Claude summary not in Russian — fell back to the deterministic report.' }) }];
  }
}else{
  // §3 invalid (non-JSON) summary -> fall back to the deterministic report (facts unchanged). Claude never
  // overrides counts/prices/competitors/evidence/source status; on any parse failure we keep the deterministic facts.
  return [{ json: Object.assign({}, rep, { llm_status:'fallback_deterministic', llm_model:str(cfg.llm_model)||'claude-sonnet-4-6', llm_input_tokens:inTok, llm_output_tokens:outTok, llm_cost_usd:cost, llm_summary_ru:'', llm_recommendations_ru:'', llm_quality_flags:'non_json_output; fell_back_to_deterministic', notes:str(rep.notes)+' || Claude summary invalid (non-JSON) — fell back to the deterministic report.' }) }];
}
// --- anti-hallucination check: numbers in the output that are absent from the fact payload get flagged.
const factBlob=str(prompt.llm_facts_string);
const outNums=(summaryRu+' '+recsRu).match(/\d{2,}/g)||[];
if(outNums.some(n=>factBlob.indexOf(n)<0))flags.push('unverified_numbers_check_manually');
// --- outreach guard: flag if the model slipped into outreach language despite the system prompt.
if(/аутрич|рассылк|обзвон|написать ему|связаться с автором/i.test(summaryRu+' '+recsRu))flags.push('outreach_language_detected_review');
const llmStatus=flags.length?'ok_with_flags':'ok';
return [{ json: Object.assign({}, rep, {
  llm_status:llmStatus,
  llm_model:str(cfg.llm_model)||'claude-sonnet-4-6',
  llm_input_tokens:inTok,
  llm_output_tokens:outTok,
  llm_cost_usd:cost,
  llm_summary_ru:summaryRu.slice(0,4000),
  llm_recommendations_ru:recsRu.slice(0,2000),
  llm_quality_flags:flags.join(', '),
  notes:str(rep.notes)+' || llm_summary added (model='+(str(cfg.llm_model)||'claude-sonnet-4-6')+', input_tokens='+inTok+', output_tokens='+outTok+', cost_usd='+cost+', flags='+(flags.join('/')||'none')+'); evidence-bound prompt + budget guard (DEC-128), no invented facts/contacts/outreach.'
}) }];

// Build ONE live_source_runs row for the report layer (23 columns, DEC-126/128): logs whether the run
// was deterministic ($0) or used the approved Claude branch, with token/cost accounting.
function str(v){return v==null?'':String(v).trim();}
const cfg=$('Set Report Config').first().json;
let rep=$('Build Deterministic Report').first().json;
try{ rep=Object.assign({},rep,$('Append market_intelligence_reports').first().json); }catch(e){}
const llmUsed=str(rep.llm_status)!==''&&str(rep.llm_status)!=='disabled';
return [{ json: {
  run_id:str(cfg.run_id),
  created_at:str(cfg.created_at),
  workflow:'WF12 - Market Intelligence Report Builder',
  source_family:'report_layer',
  platform:'sheets',
  mode:llmUsed?'llm_summary':'deterministic',
  approval_token_used:llmUsed?'yes':'no',
  source_allowlist:'',
  max_items:0,
  items_received:Number(rep.rows_after_filters)||0,
  items_relevant:Number(rep.rows_after_filters)||0,
  items_written_raw:1,
  items_unique:1,
  items_duplicate:0,
  hard_skipped:0,
  external_calls:llmUsed?1:0,
  estimated_source_cost_usd:0,
  llm_calls:llmUsed?1:0,
  estimated_llm_cost_usd:Number(rep.llm_cost_usd)||0,
  status:'completed',
  error_summary:'',
  operator_next_action:(str(rep.report_type)==='no_data_notice')?'no_data; broaden filters/sources, re-run WF10 then WF12.':'Review the report row'+(llmUsed?' incl. llm_summary_ru / llm_quality_flags; record cost in COSTS_AND_LIMITS.md.':'.'),
  notes:'wf12 v0.3 report run; report_id='+str(rep.report_id)+'; llm_status='+(str(rep.llm_status)||'disabled')+'.'
}}];
